            for offset,size,label in [(0,halves[0],'left'),(halves[0],halves[1],'right')]:
                numbers=vals[offset:offset+size-1]
                avg=vals[offset+size-1]
                calc=sum(numbers)/len(numbers)
                if abs(calc-avg)>0.02:
                    print(section,row.group(1),label,'values',numbers,'reported',avg,'calculated',round(calc,4))
